    gusset(context, id + "gusset1", { "edges" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "frame1", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(95, 5, 0) * millimeter), "gussetType" : GussetStyleType.TRIANGLE, "length" : 15 * millimeter, "shouldFlipBaseSides" : false, "thickness" : 2 * millimeter, "gussetPosition" : GussetPosition.ALIGNED, "alignedReference" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "other", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(95, 25, 2) * millimeter), "shouldFlipAlignment" : false, "offset" : 0 * millimeter, "shouldFlipOffset" : false, "baseSweptFaces" : qNothing() });
